create table if not exists public.market_snapshots (id bigint generated always as identity primary key, user_id uuid not null references auth.users(id) on delete cascade, mode text not null check (mode in ('paper','live')), symbol text not null, price numeric(24,8) not null check (price>0), bid numeric(24,8), ask numeric(24,8), spread_percent numeric(12,6), bid_depth numeric(24,8), ask_depth numeric(24,8), book_imbalance numeric(12,8), data_quality numeric(8,6) not null default 1, created_at timestamptz not null default now());
create index if not exists market_snapshots_user_mode_symbol_created_idx on public.market_snapshots(user_id,mode,symbol,created_at desc);
create table if not exists public.signal_decisions (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, mode text not null check (mode in ('paper','live')), symbol text not null, action text not null check (action in ('OPEN','CLOSE','WAIT','NO_TRADE')), score numeric(8,4) not null default 0, expected_edge_percent numeric(12,6), reasons jsonb not null default '[]'::jsonb, features jsonb not null default '{}'::jsonb, created_at timestamptz not null default now());
create index if not exists signal_decisions_user_mode_created_idx on public.signal_decisions(user_id,mode,created_at desc);
create table if not exists public.risk_events (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, mode text not null check (mode in ('paper','live')), symbol text, event_type text not null, severity text not null default 'info', detail jsonb not null default '{}'::jsonb, created_at timestamptz not null default now());
create index if not exists risk_events_user_created_idx on public.risk_events(user_id,created_at desc);
create table if not exists public.pair_quarantine (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, mode text not null check (mode in ('paper','live')), symbol text not null, reason text not null, locked_until timestamptz not null, created_at timestamptz not null default now(), unique(user_id,mode,symbol));
create index if not exists pair_quarantine_lookup_idx on public.pair_quarantine(user_id,mode,symbol,locked_until);
create table if not exists public.bot_health (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, mode text not null check (mode in ('paper','live')), state text not null default 'BOOT', websocket_healthy boolean not null default false, market_data_healthy boolean not null default false, private_stream_healthy boolean not null default false, db_healthy boolean not null default true, last_market_at timestamptz, last_cycle_at timestamptz, last_error text, reconnect_count integer not null default 0, updated_at timestamptz not null default now(), unique(user_id,mode));
create table if not exists public.strategy_metrics (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, mode text not null check (mode in ('paper','live')), strategy text not null, trades integer not null default 0, wins integer not null default 0, losses integer not null default 0, gross_pnl numeric(24,8) not null default 0, fees numeric(24,8) not null default 0, avg_slippage_percent numeric(12,8) not null default 0, updated_at timestamptz not null default now(), unique(user_id,mode,strategy));
create table if not exists public.orders (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, position_id uuid references public.positions(id) on delete set null, mode text not null check (mode in ('paper','live')), symbol text not null, client_order_id text not null, exchange_order_id text, side text not null check (side in ('buy','sell')), order_type text not null default 'market', status text not null default 'pending', requested_price numeric(24,8), executed_price numeric(24,8), quantity numeric(24,12), fee numeric(24,8) not null default 0, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(user_id,mode,client_order_id));
create index if not exists orders_user_created_idx on public.orders(user_id,created_at desc);
create table if not exists public.fills (id uuid primary key default gen_random_uuid(), order_id uuid not null references public.orders(id) on delete cascade, user_id uuid not null references auth.users(id) on delete cascade, mode text not null check (mode in ('paper','live')), symbol text not null, exchange_trade_id text, price numeric(24,8) not null, quantity numeric(24,12) not null, fee numeric(24,8) not null default 0, filled_at timestamptz not null default now(), unique(order_id,exchange_trade_id));
create index if not exists fills_user_created_idx on public.fills(user_id,filled_at desc);
create index if not exists market_snapshots_created_idx on public.market_snapshots(created_at desc);
create or replace function public.set_updated_at() returns trigger language plpgsql set search_path=public as $$ begin new.updated_at=now(); return new; end; $$;
drop trigger if exists bot_health_updated_at on public.bot_health; create trigger bot_health_updated_at before update on public.bot_health for each row execute function public.set_updated_at();
drop trigger if exists strategy_metrics_updated_at on public.strategy_metrics; create trigger strategy_metrics_updated_at before update on public.strategy_metrics for each row execute function public.set_updated_at();
drop trigger if exists orders_updated_at on public.orders; create trigger orders_updated_at before update on public.orders for each row execute function public.set_updated_at();
alter table public.market_snapshots enable row level security; alter table public.signal_decisions enable row level security; alter table public.risk_events enable row level security; alter table public.pair_quarantine enable row level security; alter table public.bot_health enable row level security; alter table public.strategy_metrics enable row level security; alter table public.orders enable row level security; alter table public.fills enable row level security;
drop policy if exists market_snapshots_owner on public.market_snapshots; create policy market_snapshots_owner on public.market_snapshots for select to authenticated using ((select auth.uid())=user_id);
drop policy if exists signal_decisions_owner on public.signal_decisions; create policy signal_decisions_owner on public.signal_decisions for select to authenticated using ((select auth.uid())=user_id);
drop policy if exists risk_events_owner on public.risk_events; create policy risk_events_owner on public.risk_events for select to authenticated using ((select auth.uid())=user_id);
drop policy if exists pair_quarantine_owner on public.pair_quarantine; create policy pair_quarantine_owner on public.pair_quarantine for select to authenticated using ((select auth.uid())=user_id);
drop policy if exists bot_health_owner on public.bot_health; create policy bot_health_owner on public.bot_health for select to authenticated using ((select auth.uid())=user_id);
drop policy if exists strategy_metrics_owner on public.strategy_metrics; create policy strategy_metrics_owner on public.strategy_metrics for select to authenticated using ((select auth.uid())=user_id);
drop policy if exists orders_owner on public.orders; create policy orders_owner on public.orders for select to authenticated using ((select auth.uid())=user_id);
drop policy if exists fills_owner on public.fills; create policy fills_owner on public.fills for select to authenticated using ((select auth.uid())=user_id);
grant select on public.market_snapshots,public.signal_decisions,public.risk_events,public.pair_quarantine,public.bot_health,public.strategy_metrics,public.orders,public.fills to authenticated;
grant all on public.market_snapshots,public.signal_decisions,public.risk_events,public.pair_quarantine,public.bot_health,public.strategy_metrics,public.orders,public.fills to service_role;
alter publication supabase_realtime add table public.signal_decisions;
alter publication supabase_realtime add table public.bot_health;
